/* Original demo application. Visual vocabulary informed by Vector95 and ProcGen FM.
   No original application engine is loaded. See About > Credits for font notices. */
'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = (s) => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = (name, cls = '') => `<img class="${cls}" src="assets/icons/${name}.svg" alt="">`;
const desktop = $('#desktop');
const wins = new Map();
let z = 10, activeId = null, previousDialogFocus = null;
const apps = {
  explorer:{title:'Exploring - Widget Library',short:'Widget Library',icon:'open',width:740,height:500},
  paint:{title:'Untitled - Paint',short:'Paint',icon:'brush',width:720,height:520},
  player:{title:'Media Player',short:'Media Player',icon:'media',width:376,height:390},
  display:{title:'Display Properties',short:'Display Properties',icon:'monitor',width:418,height:472},
  help:{title:'GUI95 Help',short:'Reference Help',icon:'info',width:570,height:470},
  picture:{title:'Vector95 - Source Reference',short:'Source Reference',icon:'logo',width:740,height:530}
};
const colorNames = [['Teal','#008080'],['Navy','#000080'],['Spruce','#004040'],['Plum','#400040'],['Slate','#404040'],['Classic gray','#808080']];
let displaySettings = {color:'#008080',pattern:'plain',font:'Tahoma',large:false};
let displayDraft = {...displaySettings};
const announce = message => { $('#announcer').textContent = message; };
function status(id,message){const node=$(`#${id}-status`);if(node)node.textContent=message;}
function fitWindow(el){
  const maxW=desktop.clientWidth, maxH=desktop.clientHeight;
  if(el.classList.contains('maximized')){Object.assign(el.style,{left:'0px',top:'0px',width:`${maxW}px`,height:`${maxH}px`});return;}
  const width=Math.min(parseFloat(el.style.width),maxW-12),height=Math.min(parseFloat(el.style.height),maxH-12);
  el.style.width=`${width}px`;el.style.height=`${height}px`;
  el.style.left=`${Math.max(0,Math.min(parseFloat(el.style.left)||0,maxW-width))}px`;
  el.style.top=`${Math.max(0,Math.min(parseFloat(el.style.top)||0,maxH-height))}px`;
}
function activate(id,focus=false){
  const el=wins.get(id);if(!el)return;
  el.hidden=false;activeId=id;el.style.zIndex=++z;
  for(const [key,win] of wins)win.classList.toggle('active',key===id);
  updateTasks();if(focus)el.focus({preventScroll:true});
}
function updateTasks(){
  $('#tasks').innerHTML=[...wins].map(([id,el])=>`<button data-task="${id}" aria-pressed="${!el.hidden&&id===activeId}" title="${esc(apps[id].title)}">${icon(apps[id].icon)}<span>${esc(apps[id].short)}</span></button>`).join('');
}
function nextActive(){const next=[...wins].filter(([,el])=>!el.hidden).sort((a,b)=>Number(b[1].style.zIndex)-Number(a[1].style.zIndex))[0];activeId=null;if(next)activate(next[0]);else updateTasks();}
function minimize(id){wins.get(id).hidden=true;closeMenu();nextActive();announce(`${apps[id].short} minimized. Restore it from the taskbar.`);}
function closeWindow(id,force=false){
  closeMenu();const el=wins.get(id);if(!el)return;
  if(id==='paint'&&paintDirty&&!force){showDialog('Paint','<p>Save changes to Untitled?</p>',[{label:'Yes',run:()=>{savePaint();closeWindow(id,true);}},{label:'No',run:()=>closeWindow(id,true)},{label:'Cancel'}]);return;}
  if(id==='player')stopAudio();if(id==='display')applyDisplay(displaySettings);
  el.remove();wins.delete(id);nextActive();announce(`${apps[id].short} closed.`);
}
function maximize(id){const el=wins.get(id);if(!el||id==='display')return;const maximized=el.classList.toggle('maximized');
  if(maximized){el.dataset.restore=JSON.stringify({left:el.style.left,top:el.style.top,width:el.style.width,height:el.style.height});}
  else Object.assign(el.style,JSON.parse(el.dataset.restore));
  const btn=$('[data-window-action="maximize"]',el);btn.setAttribute('aria-label',maximized?'Restore window':'Maximize window');btn.dataset.captionIcon=maximized?'restore':'maximize';fitWindow(el);activate(id);
}
function openApp(id){
  closeMenu();closeStart();if(wins.has(id)){activate(id,true);return wins.get(id);}
  const app=apps[id],el=document.createElement('section');el.className='window';el.id=`window-${id}`;el.dataset.app=id;el.tabIndex=-1;el.setAttribute('aria-label',app.title);
  const narrow=desktop.clientWidth<720;
  let left=124+wins.size*28,top=54+wins.size*25;
  if(id==='player'&&!narrow){left=Math.max(420,desktop.clientWidth-425);top=Math.max(130,desktop.clientHeight-429);}
  if(id==='display'){left=(desktop.clientWidth-app.width)/2;top=(desktop.clientHeight-app.height)/2;}
  if(narrow){left=6;top=82;}
  Object.assign(el.style,{left:`${left}px`,top:`${top}px`,width:`${Math.min(app.width,desktop.clientWidth-12)}px`,height:`${Math.min(app.height,desktop.clientHeight-(narrow?90:20))}px`});
  el.innerHTML=`<header class="titlebar">${icon(app.icon)}<strong>${esc(app.title)}</strong><div class="caption-controls gui95-caption-controls"><button type="button" class="gui95-caption-button" data-caption-icon="minimize" data-window-action="minimize" aria-label="Minimize window"></button><button type="button" class="gui95-caption-button" data-caption-icon="maximize" data-window-action="maximize" aria-label="Maximize window"></button><button type="button" class="gui95-caption-button" data-caption-icon="close" data-window-action="close" aria-label="Close window"></button></div></header><div class="window-body"></div>${id==='display'?'':['n','e','s','w','ne','nw','se','sw'].map(edge=>`<div class="resize-handle resize-${edge}" data-resize="${edge}" title="Drag border to resize" aria-hidden="true"></div>`).join('')}`;
  if(id==='display'){$('[data-window-action="minimize"]',el).remove();$('[data-window-action="maximize"]',el).remove();}
  $('#windows').append(el);wins.set(id,el);
  el.addEventListener('pointerdown',()=>activate(id));el.addEventListener('focusin',()=>{if(activeId!==id)activate(id);});
  $('.titlebar',el).addEventListener('dblclick',e=>{if(!e.target.closest('button'))maximize(id);});
  $('.titlebar',el).addEventListener('pointerdown',e=>startWindowGesture(e,el,false));
  $$('.resize-handle',el).forEach(handle=>handle.addEventListener('pointerdown',e=>startWindowGesture(e,el,handle.dataset.resize)));
  el.addEventListener('click',e=>{const cmd=e.target.closest('[data-window-action]')?.dataset.windowAction;if(cmd==='close')closeWindow(id);if(cmd==='minimize')minimize(id);if(cmd==='maximize')maximize(id);});
  renderers[id]( $('.window-body',el) );fitWindow(el);activate(id);return el;
}
function resizeBounds(start,edge,dx,dy,maxWidth,maxHeight){
  let left=start.left,top=start.top,right=left+start.width,bottom=top+start.height;
  if(edge.includes('w'))left=Math.max(0,Math.min(left+dx,right-280));
  if(edge.includes('e'))right=Math.min(maxWidth,Math.max(right+dx,left+280));
  if(edge.includes('n'))top=Math.max(0,Math.min(top+dy,bottom-170));
  if(edge.includes('s'))bottom=Math.min(maxHeight,Math.max(bottom+dy,top+170));
  return {left,top,width:right-left,height:bottom-top};
}
function startWindowGesture(event,el,resize){
  if(event.button!==0||event.target.closest('button')||el.classList.contains('maximized'))return;
  const handle=event.currentTarget;event.preventDefault();handle.setPointerCapture(event.pointerId);
  const start={x:event.clientX,y:event.clientY,left:parseFloat(el.style.left),top:parseFloat(el.style.top),width:el.offsetWidth,height:el.offsetHeight};
  const move=e=>{const dx=e.clientX-start.x,dy=e.clientY-start.y;if(resize){const bounds=resizeBounds(start,resize,dx,dy,desktop.clientWidth,desktop.clientHeight);for(const [key,value] of Object.entries(bounds))el.style[key]=`${value}px`;}else{el.style.left=`${Math.max(0,Math.min(start.left+dx,desktop.clientWidth-el.offsetWidth))}px`;el.style.top=`${Math.max(0,Math.min(start.top+dy,desktop.clientHeight-el.offsetHeight))}px`;}};
  const end=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);handle.removeEventListener('pointercancel',end);handle.removeEventListener('lostpointercapture',end);if(handle.hasPointerCapture(event.pointerId))handle.releasePointerCapture(event.pointerId);};
  handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',end);handle.addEventListener('lostpointercapture',end);
}
const menuDefinitions={
  explorer:{File:[['Open selected item','openSelected','Enter'],null,['Close','close']],View:[['Large Icons','icons'],['Details','details'],null,['Refresh','refresh','F5']],Help:[['Help Topics','help','F1'],['About this desktop','about']]},
  paint:{File:[['New','newPaint','Ctrl+N'],['Save As...','savePaint','Ctrl+S'],null,['Close','close']],Edit:[['Undo','undo','Ctrl+Z'],['Clear Image...','clearPaint']],Image:[['Draw Text...','textPaint'],['Custom Color...','colorPaint']],Help:[['Paint Help','paintHelp'],['About this desktop','about']]},
  player:{File:[['Close','close']],Playback:[['Play / Pause','play','Space'],['Stop','stop'],['Next Track','next'],null,['Repeat','repeat']],Help:[['About this player','playerHelp']]},
  help:{File:[['Close','close']],Help:[['Contents','helpContents'],['About this desktop','about']]},
  picture:{File:[['Close','close']],View:[['Fit to Window','fitPicture'],['Actual Size','actualPicture']],Help:[['Source notes','sourceHelp']]}
};
function menuBar(id){return `<nav class="menubar" aria-label="${apps[id].short} menu">${Object.keys(menuDefinitions[id]||{}).map(name=>`<button class="menu-trigger" data-menu="${name}" data-owner="${id}" aria-haspopup="menu" aria-expanded="false"><u>${name[0]}</u>${name.slice(1)}</button>`).join('')}</nav>`;}
let currentMenu=null,menuFocus=null,trackingMenu=false;
function closeMenu(restore=false){$('#menu-popup').hidden=true;$$('.menu-trigger').forEach(x=>x.setAttribute('aria-expanded','false'));currentMenu=null;trackingMenu=false;if(restore&&menuFocus?.isConnected)menuFocus.focus();}
function showMenu(trigger,focus=false){
  closeStart();const owner=trigger.dataset.owner,name=trigger.dataset.menu;const old=currentMenu;closeMenu();if(!old)menuFocus=document.activeElement;
  currentMenu={owner,name,trigger};trigger.setAttribute('aria-expanded','true');const popup=$('#menu-popup');
  popup.innerHTML=menuDefinitions[owner][name].map(item=>item?`<button role="menuitem" data-command="${item[1]}" ${item[1]==='undo'&&!paintHistory.length?'disabled':''}><span class="check">${(item[1]==='repeat'&&audioState.repeat)||(item[1]==='details'&&detailsView)||(item[1]==='icons'&&!detailsView)?'✓':''}</span>${esc(item[0])}<span class="shortcut">${item[2]||''}</span></button>`:'<hr role="separator">').join('');
  popup.hidden=false;const rect=trigger.getBoundingClientRect();popup.style.left=`${Math.max(0,Math.min(rect.left,innerWidth-popup.offsetWidth-3))}px`;popup.style.top=`${Math.min(rect.bottom,innerHeight-popup.offsetHeight-36)}px`;
  if(focus)$('button:not(:disabled)',popup)?.focus();
}
document.addEventListener('pointerdown',event=>{
  const trigger=event.target.closest('.menu-trigger');if(trigger){event.preventDefault();if(currentMenu?.trigger===trigger)closeMenu();else{showMenu(trigger);trackingMenu=true;}return;}
  if(!event.target.closest('#menu-popup'))closeMenu();if(!event.target.closest('#start-menu,#start'))closeStart();
});
document.addEventListener('pointerover',event=>{const trigger=event.target.closest('.menu-trigger');if(trigger&&currentMenu&&trigger!==currentMenu.trigger){const wasTracking=trackingMenu;showMenu(trigger);trackingMenu=wasTracking;}});
document.addEventListener('pointerup',event=>{if(!trackingMenu)return;const command=event.target.closest('#menu-popup [data-command]');trackingMenu=false;if(command&&!command.disabled){const owner=currentMenu.owner;closeMenu(true);runCommand(command.dataset.command,owner);}});
document.addEventListener('click',event=>{const trigger=event.target.closest('.menu-trigger');if(trigger&&event.detail===0)showMenu(trigger,true);});
$('#menu-popup').addEventListener('click',event=>{const button=event.target.closest('[data-command]');if(!button||!currentMenu)return;const owner=currentMenu.owner;closeMenu(true);runCommand(button.dataset.command,owner);});
function runCommand(command,owner=activeId){
  const actions={close:()=>closeWindow(owner),help:()=>showHelp('welcome'),about:showAbout,icons:()=>{detailsView=false;renderFolder();},details:()=>{detailsView=true;renderFolder();},refresh:renderFolder,openSelected:openSelectedFile,newPaint:()=>confirmClear(true),clearPaint:()=>confirmClear(false),undo:undoPaint,savePaint,textPaint:showTextDialog,colorPaint:showColorDialog,play:toggleAudio,stop:stopAudio,next:nextTrack,repeat:()=>{audioState.repeat=!audioState.repeat;updatePlayer();},paintHelp:()=>showHelp('paint'),playerHelp:()=>showHelp('player'),helpContents:()=>showHelp('welcome'),sourceHelp:()=>showHelp('sources'),fitPicture:()=>{$('.picture-scroll img').style.width='100%';},actualPicture:()=>{$('.picture-scroll img').style.width='1480px';}};
  actions[command]?.();
}
function attachOpenBehavior(root,selector,select,open){root.addEventListener('click',e=>{const item=e.target.closest(selector);if(item){select(item);if(e.detail===0)open(item);}});root.addEventListener('dblclick',e=>{const item=e.target.closest(selector);if(item)open(item);});}
const desktopEntries=[['explorer','open','Widget Library'],['paint','brush','Paint'],['player','media','Media Player'],['display','monitor','Display'],['help','info','Reference Help']];
$('#desktop-icons').innerHTML=desktopEntries.map(([id,img,label])=>`<button class="desktop-icon" data-open="${id}" title="Double-click to open ${label}">${icon(img)}<span>${label}</span></button>`).join('');
attachOpenBehavior($('#desktop-icons'),'.desktop-icon',item=>{$$('.desktop-icon').forEach(x=>x.classList.toggle('selected',x===item));},item=>openApp(item.dataset.open));
$('#tasks').addEventListener('click',event=>{const id=event.target.closest('[data-task]')?.dataset.task;if(!id)return;const win=wins.get(id);if(!win.hidden&&activeId===id)minimize(id);else activate(id,true);});
$('#start-items').innerHTML=desktopEntries.map(([id,img,label])=>`<button role="menuitem" data-open="${id}">${icon(img)}${label}</button>`).join('')+'<hr><button role="menuitem" data-reset="true">'+icon('undo')+'Reset Desktop...</button>';
function closeStart(){$('#start-menu').hidden=true;$('#start').setAttribute('aria-expanded','false');}
$('#start').addEventListener('click',()=>{const open=$('#start-menu').hidden;closeMenu();$('#start-menu').hidden=!open;$('#start').setAttribute('aria-expanded',String(open));if(open)$('button',$('#start-menu')).focus();});
$('#start-items').addEventListener('click',event=>{const btn=event.target.closest('button');if(!btn)return;closeStart();if(btn.dataset.open)openApp(btn.dataset.open);else showDialog('Reset Desktop','<p>Restore the original window layout and display settings? Your current drawing will be cleared.</p>',[{label:'Reset',run:resetDesktop},{label:'Cancel'}]);});

// Explorer: folders, item selection, views, and a keyboard-adjustable split pane.
let currentFolder='home',selectedFile=0,detailsView=false;
const folders={
 home:{title:'Widget Library',description:'A working collection of classic desktop interactions.',note:'Double-click an item to open it. Try the menus, drag a title bar, or resize a window from any edge or corner.',files:[['Control Panel','monitor','folder','controls'],['Desktop Programs','open','folder','programs'],['Reference Manuals','info','folder','manuals'],['Source Projects','logo','folder','sources'],['Read Me','text','help','welcome']]},
 controls:{title:'Control Panel',description:'Change how your desktop looks and behaves.',note:'Display Properties puts tabs, radio buttons, checkboxes, preview panes, and OK / Cancel / Apply to work.',files:[['Display','monitor','app','display'],['Media Player','media','app','player'],['Paint','brush','app','paint'],['Keyboard & Mouse','info','help','keyboard']]},
 programs:{title:'Desktop Programs',description:'Open a program and make something happen.',note:'These are purpose-built demonstrations. Paint makes a real PNG; Media Player generates a small tune in your browser.',files:[['Paint','brush','app','paint'],['Media Player','media','app','player'],['GUI95 Help','info','app','help']]},
 manuals:{title:'Reference Manuals',description:'Original guidance, with editions kept distinct.',note:'Read the guide notes in GUI95 Help. Internet links open the original references in a new browser tab.',files:[['Interface Guidelines, 1995','text','help','manuals'],['Usability Study, 1996','text','link','https://chi1996.acm.org/proceedings/desbrief/Sullivan/kds_txt.html'],['Common Controls','text','help','controls']]},
 sources:{title:'Source Projects',description:'The real applications behind this reference.',note:'The screenshots are preserved examples from Vector95. The controls on this desktop are interactive adaptations.',files:[['Vector95 Workspace','logo','picture','workspace'],['Vector95 Text Dialog','text','picture','dialog'],['Vector95 & ProcGen FM','info','help','sources'],['Font Credits','text','help','credits']]}
};
function explorerHTML(){return `${menuBar('explorer')}<div class="toolbar"><button data-folder="home" title="Up to Widget Library">${icon('up')}Up</button><span class="separator"></span><button data-view="icons" aria-pressed="${!detailsView}" title="Large icons">${icon('grid')}Icons</button><button data-view="details" aria-pressed="${detailsView}" title="Details view">${icon('layers')}Details</button><span class="separator"></span><button data-open="help">${icon('info')}Help</button></div><label class="address">Address<input aria-label="Current folder" value="C:\\Widget Library" readonly></label><div class="explorer-split"><nav class="tree" aria-label="Folders">${Object.entries(folders).map(([id,f])=>`<button data-folder="${id}" class="${id===currentFolder?'selected':''}" ${id===currentFolder?'aria-current="page"':''}>${icon(id==='home'?'logo':'open')}<span>${f.title}</span></button>`).join('')}</nav><div class="splitter" tabindex="0" role="separator" aria-label="Folder pane width" aria-orientation="vertical" aria-valuemin="106" aria-valuemax="290" aria-valuenow="166"></div><div class="folder-view"></div></div><div class="statusbar"><span id="explorer-status"></span><span>My Computer</span></div>`;}
function renderFolder(){
  const win=wins.get('explorer');if(!win)return;const f=folders[currentFolder];selectedFile=Math.min(selectedFile,f.files.length-1);
  $('.folder-view',win).innerHTML=`<div class="folder-heading">${icon(currentFolder==='home'?'logo':'open')}<div><h2>${f.title}</h2><p>${f.description}</p></div></div><div class="files ${detailsView?'details':''}" aria-label="Folder items">${f.files.map(([name,img,type],i)=>`<button class="file ${selectedFile===i?'selected':''}" data-file="${i}" title="Double-click to open ${esc(name)}">${icon(img)}<span>${esc(name)}</span><span class="file-type">${type==='folder'?'File Folder':type==='app'?'Application':type==='picture'?'Image':'Help Topic'}</span></button>`).join('')}</div><p class="folder-note">${f.note}</p>`;
  $('.address input',win).value='C:\\Widget Library'+(currentFolder==='home'?'':'\\'+f.title);
  $$('[data-folder]',win).forEach(b=>{b.classList.toggle('selected',b.closest('.tree')&&b.dataset.folder===currentFolder);if(b.closest('.tree')){if(b.dataset.folder===currentFolder)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}});
  $$('[data-view]',win).forEach(b=>b.setAttribute('aria-pressed',String(detailsView===(b.dataset.view==='details'))));
  status('explorer',`${f.files.length} object(s) · Double-click to open`);
}
function openSelectedFile(){const [name,,type,target]=folders[currentFolder].files[selectedFile];
  if(type==='folder'){currentFolder=target;selectedFile=0;renderFolder();}
  else if(type==='app')openApp(target);else if(type==='help')showHelp(target);else if(type==='picture')showPicture(target);else window.open(target,'_blank','noopener,noreferrer');
  announce(`Opened ${name}`);
}
function setupExplorer(body){body.innerHTML=explorerHTML();renderFolder();
  body.addEventListener('click',e=>{const f=e.target.closest('[data-folder]');if(f){currentFolder=f.dataset.folder;selectedFile=0;renderFolder();}const view=e.target.closest('[data-view]');if(view){detailsView=view.dataset.view==='details';renderFolder();}if(e.target.closest('[data-open="help"]'))showHelp('welcome');});
  attachOpenBehavior(body,'.file',item=>{selectedFile=Number(item.dataset.file);$$('.file',body).forEach(b=>b.classList.toggle('selected',b===item));status('explorer',`${folders[currentFolder].files[selectedFile][0]} selected`);},()=>openSelectedFile());
  body.addEventListener('keydown',e=>{if(!e.target.closest('.file'))return;const list=$$('.file',body);let i=Number(e.target.dataset.file);if(e.key==='ArrowRight'||e.key==='ArrowDown')i=Math.min(list.length-1,i+1);else if(e.key==='ArrowLeft'||e.key==='ArrowUp')i=Math.max(0,i-1);else return;e.preventDefault();selectedFile=i;list[i].focus();list[i].classList.add('selected');list.forEach((b,n)=>b.classList.toggle('selected',n===i));});
  const split=$('.splitter',body),tree=$('.tree',body);const resize=value=>{const width=Math.max(106,Math.min(290,body.clientWidth-150,value));tree.style.width=`${width}px`;split.setAttribute('aria-valuenow',String(Math.round(width)));};
  split.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();resize(e.key==='Home'?106:e.key==='End'?290:tree.offsetWidth+(e.key==='ArrowRight'?8:-8));});
  split.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();split.setPointerCapture(e.pointerId);const start=e.clientX,width=tree.offsetWidth;const move=ev=>resize(width+ev.clientX-start);const end=()=>{split.removeEventListener('pointermove',move);split.removeEventListener('pointerup',end);split.removeEventListener('pointercancel',end);};split.addEventListener('pointermove',move);split.addEventListener('pointerup',end);split.addEventListener('pointercancel',end);});
}

// Properties use a draft: Apply commits, Cancel discards, OK commits and closes.
function applyDisplay(settings){document.documentElement.style.setProperty('--desktop',settings.color);document.documentElement.style.setProperty('--font',settings.font==='Tahoma'?'Tahoma, Arial, sans-serif':'System95, Tahoma, sans-serif');document.documentElement.style.setProperty('--ui-size',settings.font==='Tahoma'?'12px':'11px');document.body.classList.toggle('pattern-grid',settings.pattern==='grid');document.body.classList.toggle('pattern-dots',settings.pattern==='dots');document.body.classList.toggle('large-text',settings.large);}
function displayPreview(){const screen=$('#display-preview');if(screen){screen.style.background=displayDraft.color;screen.style.backgroundImage=displayDraft.pattern==='grid'?'repeating-linear-gradient(0deg,#ffffff33 0 1px,transparent 1px 8px),repeating-linear-gradient(90deg,#ffffff33 0 1px,transparent 1px 8px)':displayDraft.pattern==='dots'?'radial-gradient(#0006 1px,transparent 1px)':'none';screen.style.backgroundSize=displayDraft.pattern==='dots'?'4px 4px':'auto';}const sample=$('#font-preview');if(sample){sample.style.fontFamily=displayDraft.font==='Tahoma'?'Tahoma, Arial, sans-serif':'System95, Tahoma, sans-serif';sample.style.fontSize=displayDraft.large?'14px':displayDraft.font==='Tahoma'?'12px':'11px';}const apply=$('#apply-display');if(apply)apply.disabled=JSON.stringify(displayDraft)===JSON.stringify(displaySettings);}
function setupDisplay(body){displayDraft={...displaySettings};body.innerHTML=`<div class="property-body"><div class="tabs" role="tablist" aria-label="Display settings"><button role="tab" id="background-tab" aria-selected="true" aria-controls="background-panel" data-tab="background">Background</button><button role="tab" id="appearance-tab" aria-selected="false" aria-controls="appearance-panel" tabindex="-1" data-tab="appearance">Appearance</button></div><section class="tab-panel" id="background-panel" role="tabpanel" aria-labelledby="background-tab"><div class="monitor"><div id="display-preview" class="monitor-screen"><div class="mini-window"><div class="mini-caption">Active Window</div><p>Window Text</p></div></div></div><div class="monitor-base"></div><div class="property-grid"><label>Desktop color<select id="desktop-color">${colorNames.map(([name,color])=>`<option value="${color}" ${color===displayDraft.color?'selected':''}>${name}</option>`).join('')}</select></label><label>Pattern<select id="desktop-pattern"><option value="plain">(None)</option><option value="grid">Graph Paper</option><option value="dots">Dither</option></select></label></div><p style="margin-top:15px">Select a color and pattern, then choose Apply.</p></section><section class="tab-panel" id="appearance-panel" role="tabpanel" aria-labelledby="appearance-tab" hidden><fieldset class="property-options"><legend>Interface font</legend><label><input type="radio" name="interface-font" value="System95" ${displayDraft.font==='System95'?'checked':''}>MS Sans Serif recreation (pixel reference)</label><label><input type="radio" name="interface-font" value="Tahoma" ${displayDraft.font==='Tahoma'?'checked':''}>Tahoma (Vector95 · default)</label></fieldset><div id="font-preview" class="sample-text">Source Projects · Settings · Save As<br><b>Window titles and button labels</b></div><label><input id="large-text" type="checkbox" ${displayDraft.large?'checked':''}>Use larger text</label><p style="margin-top:14px">Tahoma is the readable default. The pixel recreation may show gaps at some display scales.</p></section><div class="dialog-actions"><button class="primary" id="ok-display">OK</button><button id="cancel-display">Cancel</button><button id="apply-display" disabled>Apply</button></div></div>`;
  $('#desktop-pattern').value=displayDraft.pattern;
  const selectTab=tab=>{$$('[role=tab]',body).forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;$(`#${t.getAttribute('aria-controls')}`).hidden=!active;});};
  $('.tabs',body).addEventListener('click',e=>{const tab=e.target.closest('[role=tab]');if(tab)selectTab(tab);});
  $('.tabs',body).addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('[role=tab]',body),index=tabs.indexOf(document.activeElement);const tab=tabs[e.key==='Home'?0:e.key==='End'?1:1-index];selectTab(tab);tab.focus();}});
  body.addEventListener('change',()=>{displayDraft={color:$('#desktop-color').value,pattern:$('#desktop-pattern').value,font:$('[name=interface-font]:checked').value,large:$('#large-text').checked};displayPreview();});
  const commit=()=>{displaySettings={...displayDraft};applyDisplay(displaySettings);displayPreview();announce('Display settings applied.');};
  $('#apply-display').addEventListener('click',commit);$('#ok-display').addEventListener('click',()=>{commit();closeWindow('display');});$('#cancel-display').addEventListener('click',()=>closeWindow('display'));displayPreview();
}

// Paint: real raster editing, bounded undo history, palette, shapes, text and PNG export.
let canvas=null,ctx=null,paintTool='pencil',paintColor='#000000',paintHistory=[],paintDirty=false;
const paintColors=['#000000','#808080','#800000','#808000','#008000','#008080','#000080','#800080','#808040','#004040','#0080ff','#004080','#8000ff','#804000','#ffffff','#c0c0c0','#ff0000','#ffff00','#00ff00','#00ffff','#0000ff','#ff00ff','#ffff80','#00ff80','#80ffff','#8080ff','#ff0080','#ff8040'];
function setupPaint(body){paintHistory=[];paintTool='pencil';paintDirty=false;body.innerHTML=`${menuBar('paint')}<div class="paint-layout"><div class="paint-tools" aria-label="Painting tools">${[['pencil','pencil','Pencil'],['brush','brush','Brush'],['eraser','eraser','Eraser'],['text','text','Text'],['rect','rect','Rectangle'],['ellipse','ellipse','Ellipse']].map(([tool,img,name])=>`<button data-tool="${tool}" aria-label="${name}" title="${name}" aria-pressed="${tool==='pencil'}">${icon(img)}</button>`).join('')}<label class="brush-size">Width<select id="brush-width" aria-label="Brush width"><option value="1">1 px</option><option value="3" selected>3 px</option><option value="6">6 px</option><option value="12">12 px</option></select></label><button data-paint-undo title="Undo" aria-label="Undo">${icon('undo')}</button><button data-paint-clear title="Clear Image" aria-label="Clear Image">${icon('new')}</button></div><div class="canvas-scroll"><canvas id="paint-canvas" width="640" height="360" tabindex="0" aria-label="Drawing canvas. Draw with the pointer; use Image, Draw Text for a keyboard alternative."></canvas></div></div><div class="paint-palette"><div class="current-paint" title="Current color"><i></i></div><div class="swatches" aria-label="Paint colors">${paintColors.map(color=>`<button class="swatch" style="--swatch:${color}" data-color="${color}" aria-label="Paint color ${color}" aria-pressed="${color===paintColor}"></button>`).join('')}</div><button data-custom-color>Colors...</button></div><div class="statusbar"><span id="paint-status">For Help, use the Help menu. Try drawing on the picture.</span><span>640 × 360</span></div>`;
  canvas=$('#paint-canvas');ctx=canvas.getContext('2d',{willReadFrequently:true});drawSample();setPaintColor(paintColor);
  body.addEventListener('click',e=>{const tool=e.target.closest('[data-tool]');if(tool){if(tool.dataset.tool==='text'){showTextDialog();return;}paintTool=tool.dataset.tool;$$('[data-tool]',body).forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tool===paintTool)));status('paint',`${tool.title}: drag on the image.`);}const color=e.target.closest('[data-color]');if(color)setPaintColor(color.dataset.color);if(e.target.closest('[data-custom-color]'))showColorDialog();if(e.target.closest('[data-paint-undo]'))undoPaint();if(e.target.closest('[data-paint-clear]'))confirmClear(false);});
  canvas.addEventListener('pointerdown',startPaint);canvas.addEventListener('pointermove',e=>{if(!e.buttons){const p=paintPoint(e);status('paint',`${paintTool[0].toUpperCase()+paintTool.slice(1)} · ${Math.round(p.x)}, ${Math.round(p.y)}`);}});
}
function drawSample(){ctx.fillStyle='#fff';ctx.fillRect(0,0,640,360);ctx.fillStyle='#a8d8e8';ctx.fillRect(45,30,550,270);ctx.fillStyle='#ffed8b';ctx.fillRect(478,57,48,48);ctx.fillStyle='#50786c';ctx.beginPath();ctx.moveTo(45,236);ctx.lineTo(190,86);ctx.lineTo(336,236);ctx.fill();ctx.fillStyle='#789b82';ctx.beginPath();ctx.moveTo(192,236);ctx.lineTo(365,109);ctx.lineTo(548,236);ctx.fill();ctx.fillStyle='#e8efde';ctx.beginPath();ctx.moveTo(159,117);ctx.lineTo(190,86);ctx.lineTo(220,117);ctx.lineTo(205,113);ctx.lineTo(190,122);ctx.lineTo(178,110);ctx.fill();ctx.fillStyle='#8ca96b';ctx.fillRect(45,235,550,65);ctx.fillStyle='#3e6855';for(const [x,y]of [[87,181],[498,178],[535,195]]){ctx.fillRect(x+12,y+35,8,50);ctx.beginPath();ctx.moveTo(x-5,y+47);ctx.lineTo(x+16,y);ctx.lineTo(x+36,y+47);ctx.fill();}ctx.fillStyle='#456e86';ctx.fillRect(45,276,550,24);ctx.fillStyle='#acd0d5';for(let i=0;i<10;i++)ctx.fillRect(60+i*52,285+(i%2)*6,28,2);ctx.fillStyle='#444';ctx.font='12px Tahoma';ctx.fillText('A little landscape. Make it yours.',45,328);}
function setPaintColor(color){paintColor=color;const preview=$('.current-paint i');if(preview)preview.style.background=color;$$('[data-color]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.color===color)));}
function rememberPaint(){paintHistory.push(ctx.getImageData(0,0,640,360));if(paintHistory.length>20)paintHistory.shift();paintDirty=true;}
function undoPaint(){if(!ctx||!paintHistory.length){status('paint','Nothing to undo.');return;}ctx.putImageData(paintHistory.pop(),0,0);status('paint','Last change undone.');}
function paintPoint(e){const rect=canvas.getBoundingClientRect();return{x:(e.clientX-rect.left)*canvas.width/rect.width,y:(e.clientY-rect.top)*canvas.height/rect.height};}
function startPaint(e){if(e.button!==0)return;e.preventDefault();canvas.focus();canvas.setPointerCapture(e.pointerId);rememberPaint();const base=paintHistory.at(-1),start=paintPoint(e);let last=start;const width=Number($('#brush-width').value);ctx.lineCap='round';ctx.lineJoin='round';
 const draw=event=>{const p=paintPoint(event);ctx.strokeStyle=paintTool==='eraser'?'#fff':paintColor;ctx.lineWidth=paintTool==='eraser'?width*4:paintTool==='brush'?width*2:width;
  if(paintTool==='rect'||paintTool==='ellipse'){ctx.putImageData(base,0,0);ctx.beginPath();if(paintTool==='rect')ctx.rect(start.x,start.y,p.x-start.x,p.y-start.y);else ctx.ellipse((start.x+p.x)/2,(start.y+p.y)/2,Math.abs(p.x-start.x)/2,Math.abs(p.y-start.y)/2,0,0,Math.PI*2);ctx.stroke();}
  else{ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(p.x===last.x?p.x+.01:p.x,p.y);ctx.stroke();}last=p;};
 draw(e);const end=()=>{canvas.removeEventListener('pointermove',draw);canvas.removeEventListener('pointerup',end);canvas.removeEventListener('pointercancel',end);status('paint','Image changed. Edit → Undo reverses the last stroke.');};canvas.addEventListener('pointermove',draw);canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);
}
function confirmClear(newImage){showDialog(newImage?'New Image':'Clear Image','<p>Clear the drawing to a blank canvas? You can undo this change.</p>',[{label:'Clear',run:()=>{rememberPaint();ctx.fillStyle='#fff';ctx.fillRect(0,0,640,360);status('paint','Blank canvas ready.');}},{label:'Cancel'}]);}
function savePaint(){if(!canvas)return;canvas.toBlob(blob=>{if(!blob){announce('The image could not be saved.');return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Untitled.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);status('paint','Saved as Untitled.png');paintDirty=false;},'image/png');}
function showColorDialog(){showDialog('Edit Colors',`<div class="dialog-form"><label>Choose a drawing color<input id="custom-paint-color" type="color" value="${paintColor}"></label><p>The selected color becomes the foreground color in Paint.</p></div>`,[{label:'OK',run:()=>setPaintColor($('#custom-paint-color').value)},{label:'Cancel'}]);}
function showTextDialog(){if(!canvas)return;showDialog('Draw Text','<div class="dialog-form"><label>Text<input id="paint-text" value="Hello, 1995!" maxlength="60"></label><div class="property-grid"><label>Size (pixels)<input id="paint-text-size" type="number" min="8" max="72" value="24"></label><label>Style<select id="paint-text-style"><option value="normal">Regular</option><option value="bold">Bold</option><option value="italic">Italic</option></select></label></div><p>Text is placed near the top left of the image in the current color. Undo removes it.</p></div>',[{label:'Draw',run:()=>{const text=$('#paint-text').value,size=Math.max(8,Math.min(72,Number($('#paint-text-size').value)||24));rememberPaint();ctx.fillStyle=paintColor;ctx.font=`${$('#paint-text-style').value} ${size}px Tahoma`;ctx.fillText(text,55,65);status('paint','Text added.');}},{label:'Cancel'}]);}

// A local, synthesized melody. No external stream, recordings, or autoplay.
const tracks=[{name:'01  The Desktop Waltz',sub:'Original demo melody · 3 voices',notes:[60,64,67,72,71,67,64,62,65,69,74,72,69,65,64,60],bpm:108},{name:'02  After Hours',sub:'Original demo melody · soft square wave',notes:[57,60,64,67,64,60,59,62,65,69,65,62,57,60,64,60],bpm:88},{name:'03  Modem Daydream',sub:'Original demo melody · triangle wave',notes:[60,67,72,76,74,72,67,64,62,69,74,77,76,74,69,67],bpm:126}];
let audioContext=null,gain=null,voices=[],audioTimer=null;
const audioState={playing:false,track:0,step:0,elapsed:0,repeat:false,volume:.25,muted:false,last:0};
function setupPlayer(body){body.innerHTML=`${menuBar('player')}<div class="player-body"><div class="player-screen"><div><h2 id="track-title"></h2><p id="track-subtitle"></p><p class="time-display" id="player-time">00:00</p></div><div class="meter" aria-hidden="true">${'<i></i>'.repeat(10)}</div></div><div class="transport"><button id="player-prev" aria-label="Previous track" title="Previous track">|◀</button><button id="player-play" aria-label="Play" title="Play" aria-pressed="false">▶</button><button id="player-stop" aria-label="Stop" title="Stop">■</button><button id="player-next" aria-label="Next track" title="Next track">▶|</button><span class="separator"></span><button id="player-repeat" aria-label="Repeat track" aria-pressed="false" title="Repeat track">Repeat</button></div><label class="volume-row">Volume<input id="player-volume" type="range" min="0" max="100" value="${audioState.volume*100}"><output id="volume-value">${Math.round(audioState.volume*100)}%</output></label><div class="player-list" role="listbox" aria-label="Tracks">${tracks.map((t,i)=>`<button role="option" aria-selected="${i===audioState.track}" tabindex="${i===audioState.track?0:-1}" data-track="${i}">${t.name}<span>MIDI</span></button>`).join('')}</div><p class="player-caption">A tiny synthesized soundtrack. Press Play to hear it.</p></div><div class="statusbar"><span id="player-status">Stopped</span><span>Stereo</span></div>`;
 $('#player-play').addEventListener('click',toggleAudio);$('#player-stop').addEventListener('click',stopAudio);$('#player-next').addEventListener('click',nextTrack);$('#player-prev').addEventListener('click',()=>chooseTrack((audioState.track+tracks.length-1)%tracks.length));$('#player-repeat').addEventListener('click',()=>{audioState.repeat=!audioState.repeat;updatePlayer();});$('#player-volume').addEventListener('input',e=>{audioState.volume=Number(e.target.value)/100;updateGain();$('#volume-value').value=`${e.target.value}%`;});
 $('.player-list',body).addEventListener('click',e=>{const t=e.target.closest('[data-track]');if(t)chooseTrack(Number(t.dataset.track));});$('.player-list',body).addEventListener('keydown',e=>{if(!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;e.preventDefault();let next=e.key==='Home'?0:e.key==='End'?2:(audioState.track+(e.key==='ArrowDown'?1:2))%3;chooseTrack(next);$(`[data-track="${next}"]`).focus();});updatePlayer();
}
function updateGain(){if(gain)gain.gain.setTargetAtTime(audioState.muted?0:audioState.volume*.22,audioContext.currentTime,.03);}
async function toggleAudio(){if(audioState.playing){pauseAudio();return;}
 try{if(!audioContext){const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error('Web Audio is unavailable in this browser.');audioContext=new Audio();gain=audioContext.createGain();gain.connect(audioContext.destination);}await audioContext.resume();updateGain();audioState.playing=true;audioState.last=performance.now();scheduleNote();audioTimer=setInterval(scheduleNote,60000/tracks[audioState.track].bpm/2);updatePlayer();}
 catch(error){showDialog('Media Player',`<p>Playback could not start: ${esc(error.message)}</p>`,[{label:'OK'}]);}
}
function scheduleNote(){const track=tracks[audioState.track];if(audioState.step>=track.notes.length*4){if(audioState.repeat)audioState.step=0;else{nextTrack();return;}}const note=track.notes[audioState.step%track.notes.length],now=audioContext.currentTime,duration=60000/track.bpm/2000;
 for(const [offset,level,type]of [[0,.58,audioState.track===1?'square':'triangle'],[-12,.28,'triangle'],[7,.10,'sine']]){const osc=audioContext.createOscillator(),envelope=audioContext.createGain();osc.type=type;osc.frequency.value=440*Math.pow(2,(note+offset-69)/12);envelope.gain.setValueAtTime(0,now);envelope.gain.linearRampToValueAtTime(level,now+.012);envelope.gain.exponentialRampToValueAtTime(.001,now+duration*.92);osc.connect(envelope);envelope.connect(gain);osc.start(now);osc.stop(now+duration);voices.push(osc);osc.onended=()=>{osc.disconnect();envelope.disconnect();voices=voices.filter(v=>v!==osc);};}audioState.step++;
}
function pauseAudio(){if(audioState.playing)audioState.elapsed+=(performance.now()-audioState.last)/1000;audioState.playing=false;clearInterval(audioTimer);audioTimer=null;for(const voice of voices){try{voice.stop();}catch{}}voices=[];updatePlayer();}
function stopAudio(){pauseAudio();audioState.step=0;audioState.elapsed=0;updatePlayer();}
function chooseTrack(index){const resume=audioState.playing;stopAudio();audioState.track=index;updatePlayer();if(resume)toggleAudio();}
function nextTrack(){chooseTrack((audioState.track+1)%tracks.length);}
function updatePlayer(){if(!wins.has('player'))return;$('#track-title').textContent=tracks[audioState.track].name.slice(4);$('#track-subtitle').textContent=tracks[audioState.track].sub;$('#player-play').textContent=audioState.playing?'Ⅱ':'▶';$('#player-play').setAttribute('aria-label',audioState.playing?'Pause':'Play');$('#player-play').title=audioState.playing?'Pause':'Play';$('#player-play').setAttribute('aria-pressed',String(audioState.playing));$('#player-repeat').setAttribute('aria-pressed',String(audioState.repeat));$$('[data-track]').forEach(b=>{const selected=Number(b.dataset.track)===audioState.track;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;});status('player',audioState.playing?'Playing':audioState.step?'Paused':'Stopped');updatePlayerTime();}
function updatePlayerTime(){const time=$('#player-time');if(!time)return;const seconds=Math.floor(audioState.elapsed+(audioState.playing?(performance.now()-audioState.last)/1000:0));time.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;$$('.meter i').forEach((bar,i)=>bar.style.height=`${audioState.playing&&!audioState.muted?20+Math.abs(Math.sin(performance.now()/180+i*1.2))*75:6}%`);}
$('#sound-toggle').addEventListener('click',()=>{audioState.muted=!audioState.muted;updateGain();$('#sound-toggle').setAttribute('aria-label',audioState.muted?'Unmute sound':'Mute sound');$('#sound-toggle').title=audioState.muted?'Unmute sound':'Mute sound';$('#sound-toggle').textContent=audioState.muted?'×':'♫';announce(audioState.muted?'Sound muted.':'Sound enabled.');});
setInterval(updatePlayerTime,150);

// Contextual Help uses period-style topics, including honest source and edition notes.
const helpTopics={
 welcome:{title:'Welcome to GUI95',html:'<p>GUI95 is a small, working desktop inspired by mid-1990s interfaces and the careful interface work in <b>Vector95</b> and <b>ProcGen FM</b>.</p><h3>Start with a task</h3><ul><li><b>Browse the library.</b> Double-click a folder. Use View to switch between icons and details. Drag the divider to resize the folder pane.</li><li><b>Make a picture.</b> Open Paint, choose a tool and a color, and draw. Undo a stroke or save the finished image.</li><li><b>Set the scene.</b> Open Display. Change a setting, inspect its preview, and choose Apply. Cancel leaves the desktop as it was.</li><li><b>Listen while you work.</b> Media Player makes a little tune locally. The transport, volume, and repeat controls work.</li></ul><p class="note">This is an interactive reference, not an operating-system emulator. Web adaptations are identified in the relevant topics.</p>'},
 keyboard:{title:'Using the mouse and keyboard',html:'<h3>Working with windows</h3><p>Drag a title bar to move a window. Drag any edge or corner to resize; the opposite edge stays in place. Display Properties is a fixed-size property sheet. Double-click the title bar to maximize or restore. Minimized windows remain on the taskbar.</p><h3>Finding a command</h3><p>Press <b>F10</b> for the active program’s menu, or <b>Alt + an underlined letter</b>. Use arrows to navigate, Enter to choose, and Escape to dismiss. You can also press a menu heading and drag to a command.</p><h3>Using controls</h3><p>Tab moves keyboard focus. Space activates a focused button or checkbox. Arrow keys change sliders, tracks, and property tabs. A dotted outline shows where keyboard input goes. In Explorer, use arrows between files and Enter to open one.</p><p>The folder-pane splitter is keyboard accessible: focus it and use Left / Right. Home and End choose its minimum and maximum widths.</p>'},
 paint:{title:'Drawing with Paint',html:'<p>Choose Pencil, Brush, Eraser, Rectangle, or Ellipse, then drag on the picture. The width selector changes the stroke size. Select a foreground color from the palette, or choose Colors for a custom one.</p><p><b>Image → Draw Text</b> places text near the image’s upper-left corner. This dialog also provides a keyboard-operated way to edit the picture.</p><p><b>Edit → Undo</b> (Ctrl+Z) reverses the last operation, including text and clearing the image. Up to 20 operations are retained.</p><p><b>File → Save As</b> (Ctrl+S) downloads a real PNG file. The browser manages the download; this demo does not imitate an operating-system file dialog.</p><p class="note">The drawing canvas is a small demonstration of toolbar modes, palette state, menu commands, and editing feedback. It is not Vector95’s vector engine.</p>'},
 player:{title:'Playing the demonstration tracks',html:'<p>Select a track, then press Play. Play changes to Pause during playback; Stop returns to the beginning. Previous and Next choose a different track. Repeat keeps the current melody playing.</p><p>Volume and the taskbar speaker control affect the sound. Playback only starts after an explicit action.</p><p>The three melodies are original, synthesized in the browser. The interface borrows compact transport controls, a dark display, a selection list, and persistent toggle states from the player reference. “MIDI” indicates the period-inspired arrangement; these are not loaded MIDI files.</p>'},
 controls:{title:'Why these controls belong here',html:'<p><b>Explorer</b> demonstrates a hierarchy, object selection, double-click activation, view commands, split panes, and status feedback.</p><p><b>Display Properties</b> demonstrates task grouping with property tabs, mutually exclusive radio choices, an independent checkbox, selection lists, a preview, and explicit OK / Cancel / Apply behavior.</p><p><b>Paint</b> demonstrates persistent tool modes, momentary commands, foreground color, numeric choices, a document surface, Undo, and text/color dialogs.</p><p><b>Media Player</b> demonstrates transport commands, a latched Repeat option, a continuous volume control, and a list whose selection has a visible purpose.</p><p>Raised and sunken edges communicate control state. Navy highlights show selection and active captions; dotted outlines identify keyboard focus. Disabled controls remain visible when unavailable.</p>'},
 manuals:{title:'Original manuals and guidelines',html:'<p><b>The Windows Interface Guidelines for Software Design</b>, Microsoft Press, 1995, ISBN 1-55615-679-0, is the published handbook. <a href="https://learn.microsoft.com/en-us/windows/win32/appuistart/other-resources" target="_blank" rel="noopener noreferrer">Microsoft’s bibliography</a> identifies this edition.</p><p>The freely readable <a href="https://ics.uci.edu/~kobsa/courses/ICS104/course-notes/Microsoft_WindowsGuidelines.pdf" target="_blank" rel="noopener noreferrer">February 1995 preliminary guide</a> is a different document. Its pagination does not match the final book. Look for the chapters on controls, secondary windows, window management, and visual design.</p><p><a href="https://chi1996.acm.org/proceedings/desbrief/Sullivan/kds_txt.html" target="_blank" rel="noopener noreferrer">Kent Sullivan’s 1996 usability case study</a> explains the iterations behind Windows 95.</p><p>The parent reference collection contains a fuller reading shelf, preserved source files, and a catalogue connecting widgets to their implementations.</p>'},
 sources:{title:'Vector95 and ProcGen FM',html:'<p><b>Vector95</b> provides the primary reference for editor windows, sharp bevels, menus, iconography, drawing controls, dialogs, and status help. Its current UI uses Tahoma, with an 11 px base size. GUI95 uses Tahoma at 12 px by default for clearer reading; the pixel-font recreation remains an optional reference.</p><p><b>sausage-music / ProcGen FM</b> provides the compact player reference, including its font recreation, transport controls, lists, and volume slider.</p><p>This demo has its own small application logic. It adapts their visual vocabulary and uses preserved Vector95 SVG icons. The parent collection contains the unmodified snapshots and their hashes.</p><p>Source screenshots in Explorer illustrate earlier captures of the original application; they are distinct from the live programs on this desktop.</p><p class="note">A browser-native color picker, PNG downloads, responsive window fitting, and larger-text support are modern adaptations. The page adapts period conventions for a modern browser.</p>'},
 credits:{title:'Credits and font notices',html:'<p>MS Sans Serif regular and bold recreations by <b>lou</b>, licensed under <b>Creative Commons Attribution-ShareAlike 3.0</b>. The font files are included unmodified.</p><ul><li><a href="assets/ms-sans-serif-readme.txt" target="_blank">Regular font readme</a> · <a href="assets/ms-sans-serif-license.txt" target="_blank">License</a></li><li><a href="assets/ms-sans-serif-bold-readme.txt" target="_blank">Bold font readme</a> · <a href="assets/ms-sans-serif-bold-license.txt" target="_blank">License</a></li></ul><p>Interface research and icon assets: Vector95. Player visual reference: ProcGen FM. The reference collection preserves the projects’ source and third-party notices.</p><p>Windows and Microsoft are trademarks of Microsoft. This independent reference demo is not a Microsoft product.</p>'}
};
let currentHelp='welcome';
function showHelp(topic){currentHelp=topic;openApp('help');renderHelp(topic);}
function renderHelp(topic){currentHelp=topic;const page=$('.help-page');if(!page)return;const entry=helpTopics[topic]||helpTopics.welcome;page.innerHTML=`<h2>${entry.title}</h2>${entry.html}`;page.scrollTop=0;$$('[data-help]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.help===topic)));status('help',entry.title);}
function setupHelp(body){body.innerHTML=`${menuBar('help')}<div class="help-body"><label class="help-search">Find a topic<input id="help-search" type="search" placeholder="Type a word..."></label><nav class="help-topics" aria-label="Help topics">${[['welcome','Contents'],['keyboard','Keyboard'],['controls','Controls'],['manuals','Manuals'],['sources','Sources'],['credits','Credits']].map(([id,label])=>`<button data-help="${id}" aria-pressed="false">${label}</button>`).join('')}</nav><article class="help-page"></article></div><div class="statusbar"><span id="help-status">Ready</span></div>`;body.addEventListener('click',e=>{const topic=e.target.closest('[data-help]');if(topic){$('#help-search').value='';renderHelp(topic.dataset.help);}});$('#help-search').addEventListener('input',e=>{const query=e.target.value.trim().toLowerCase();if(!query){renderHelp(currentHelp);return;}const matches=Object.entries(helpTopics).filter(([,v])=>(v.title+' '+v.html.replace(/<[^>]*>/g,' ')).toLowerCase().includes(query));$('.help-page').innerHTML=`<h2>Search results</h2>${matches.length?'<p>Select a topic:</p>'+matches.map(([id,v])=>`<p><button data-help="${id}">${esc(v.title)}</button></p>`).join(''):'<p>No topics found. Try “menu”, “color”, or “keyboard”.</p>'}`;});renderHelp(currentHelp);}
let pictureKind='workspace';
function showPicture(kind){pictureKind=kind;openApp('picture');renderPicture();}
function renderPicture(){const image=$('.picture-scroll img');if(image){image.src=`assets/vector95-${pictureKind}.png`;image.alt=pictureKind==='workspace'?'Preserved Vector95 drawing workspace screenshot':'Preserved Vector95 text properties dialog screenshot';}}
function setupPicture(body){body.innerHTML=`${menuBar('picture')}<div class="picture-scroll"><img alt=""></div><div class="statusbar"><span>Preserved source screenshot · use View for actual size</span></div>`;renderPicture();}
const renderers={explorer:setupExplorer,paint:setupPaint,player:setupPlayer,display:setupDisplay,help:setupHelp,picture:setupPicture};

function showDialog(title,html,buttons){closeMenu();closeStart();const dialog=$('#dialog');if(dialog.open)dialog.close();previousDialogFocus=document.activeElement;$('#dialog-heading').textContent=title;$('#dialog-content').innerHTML=html+`<div class="dialog-actions">${buttons.map((b,i)=>`<button class="${i===0?'primary':''}" data-dialog-action="${i}">${b.label}</button>`).join('')}</div>`;$$('[data-dialog-action]',dialog).forEach(b=>b.addEventListener('click',()=>{buttons[Number(b.dataset.dialogAction)].run?.();dialog.close();}));dialog.showModal();const field=$('input:not([type=color])',dialog);if(field){field.focus();field.select?.();}else $('[data-dialog-action="0"]',dialog).focus();}
$('.close-dialog').addEventListener('click',()=>$('#dialog').close());$('#dialog').addEventListener('close',()=>{if(previousDialogFocus?.isConnected)previousDialogFocus.focus({preventScroll:true});});
$('#dialog').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('input:not([type=color])')){e.preventDefault();$('[data-dialog-action="0"]').click();}});
function showAbout(){showDialog('About GUI95',`<div class="about-banner">${icon('logo')}<div><h2>GUI95</h2><p>Reference Desktop · Edition 1</p></div></div><p>A hands-on companion to the Vector95 and ProcGen FM widget collection.</p><p>Try a task, then look at the controls that make it possible. The drawing tools, settings, file views, and synthesized player all work.</p>`,[{label:'Credits',run:()=>showHelp('credits')},{label:'OK'}]);}
function resetDesktop(){for(const id of [...wins.keys()])closeWindow(id,true);displaySettings={color:'#008080',pattern:'plain',font:'Tahoma',large:false};applyDisplay(displaySettings);currentFolder='home';selectedFile=0;detailsView=false;openApp('explorer');if(desktop.clientWidth>900)openApp('player');activate('explorer');}
document.addEventListener('keydown',event=>{
 if($('#dialog').open)return;
 if(currentMenu||!$('#start-menu').hidden){const root=currentMenu?$('#menu-popup'):$('#start-menu'),buttons=$$('button:not(:disabled)',root),at=buttons.indexOf(document.activeElement);
  if(event.key==='Escape'){event.preventDefault();closeMenu(true);closeStart();return;}
  if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?buttons.length-1:at<0?(event.key==='ArrowUp'?buttons.length-1:0):(at+(event.key==='ArrowDown'?1:buttons.length-1)+buttons.length)%buttons.length;buttons[next]?.focus();return;}
  if(currentMenu&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();const headings=$$('.menu-trigger',wins.get(currentMenu.owner)),index=headings.indexOf(currentMenu.trigger);showMenu(headings[(index+(event.key==='ArrowRight'?1:headings.length-1))%headings.length],true);return;}
  if(event.key==='Tab'){closeMenu();closeStart();return;}
 }
 const input=event.target.matches('input,textarea,select,[contenteditable=true]');
 if(!input&&event.key==='F1'){event.preventDefault();showHelp(activeId==='paint'?'paint':activeId==='player'?'player':'welcome');}
 if(!input&&(event.key==='F10'||event.altKey&&!event.ctrlKey&&event.key.length===1)){const win=wins.get(activeId);const triggers=win?$$('.menu-trigger',win):[];const trigger=event.key==='F10'?triggers[0]:triggers.find(b=>b.dataset.menu[0].toLowerCase()===event.key.toLowerCase());if(trigger){event.preventDefault();showMenu(trigger,true);}}
 if(!input&&event.ctrlKey&&activeId==='paint'){const command={s:savePaint,z:undoPaint,n:()=>confirmClear(true)}[event.key.toLowerCase()];if(command){event.preventDefault();command();}}
 if(!input&&activeId==='player'&&event.code==='Space'&&!event.target.closest('button')){event.preventDefault();toggleAudio();}
 if(!input&&activeId==='explorer'&&event.key==='F5'){event.preventDefault();renderFolder();}
});
window.addEventListener('resize',()=>{for(const el of wins.values())fitWindow(el);closeMenu();});
window.addEventListener('blur',()=>{closeMenu();closeStart();});
window.addEventListener('pagehide',stopAudio);
function updateClock(){$('#clock').textContent=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});$('#clock').title=new Date().toLocaleDateString([],{weekday:'long',year:'numeric',month:'long',day:'numeric'});}updateClock();setInterval(updateClock,10000);
openApp('explorer');if(desktop.clientWidth>900)openApp('player');activate('explorer');


